input.newString:
export function formatCents(cents, currency = "USD") {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const dollars = Math.floor(abs / 100);
  const cents_part = abs % 100;
  return `${sign}${currency} ${dollars}.${String(cents_part).padStart(2, "0")}`;
}

