/** Totals per month, in cents, keyed "YYYY-MM". */
export function totalsByMonth(rows) {
  const totals = {};
  for (const row of rows) {
    const month = row.date.slice(0, 7);
    const cents = toCents(row.amount);
    totals[month] = (totals[month] || 0) + cents;
  }
  return totals;
}

